// The serials-library two-level queue tests. Series rows are first-class queue
// targets derived under the IDENTICAL predicates as items (D5): the fixtures
// below put one series row AND one episode item into the same library and drive
// the shipped Queue over both.

// fnSource is a scripted MetadataSource with per-RPC closures; Merge defaults to
// the shipped namespace-wrap (sources.<id> + one view binding per field), the
// same shape the bundled plugins' Merge emits. An unset convert returns EMPTY
// metadata (the no_data path); an unset match applies unconditionally.
type fnSource struct {
	id      string
	match   func(*metadatav1.MatchRequest) (*metadatav1.MatchResult, error)
	convert func(*metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error)
}

func (f *fnSource) Match(_ context.Context, req *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
	if f.match != nil {
		return f.match(req)
	}
	return &metadatav1.MatchResult{Applies: true}, nil
}

func (*fnSource) BuildRequest(context.Context, *metadatav1.BuildRequestRequest) (*metadatav1.BuildRequestResponse, error) {
	return &metadatav1.BuildRequestResponse{Spec: &metadatav1.RequestSpec{}}, nil
}

func (f *fnSource) Convert(_ context.Context, req *metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
	if f.convert != nil {
		return f.convert(req)
	}
	return &metadatav1.ConvertResult{}, nil // empty metadata -> no_data terminal
}

func (f *fnSource) Merge(_ context.Context, req *metadatav1.MergeRequest) (*metadatav1.MergeResult, error) {
	id := req.GetPluginId()
	if id == "" {
		id = f.id
	}
	meta := map[string]any{}
	if req.GetIncoming() != nil {
		meta = req.GetIncoming().AsMap()
	}
	data, _ := structpb.NewStruct(map[string]any{"sources": map[string]any{id: meta}})
	view := make([]*commonv1.ViewBinding, 0, len(meta))
	for field := range meta {
		view = append(view, &commonv1.ViewBinding{FieldPath: field, Source: id, Reason: "priority"})
	}
	return &metadatav1.MergeResult{Document: &commonv1.MediaDocument{Data: data}, View: view}, nil
}

// matchErrSource is a source whose Match RPC errors — the chain's outcomeFailed
// path (retried, then terminal exhausted).
type matchErrSource struct{ id string }

func (m *matchErrSource) Match(context.Context, *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
	return nil, errors.New("match rpc failed") // any RPC error; the kind, not the cause, matters
}
func (*matchErrSource) BuildRequest(context.Context, *metadatav1.BuildRequestRequest) (*metadatav1.BuildRequestResponse, error) {
	return &metadatav1.BuildRequestResponse{}, nil
}
func (*matchErrSource) Convert(context.Context, *metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
	return &metadatav1.ConvertResult{}, nil
}
func (m *matchErrSource) Merge(_ context.Context, req *metadatav1.MergeRequest) (*metadatav1.MergeResult, error) {
	return (&fnSource{id: m.id}).Merge(context.Background(), req)
}

// serialDoc is a freshly-scanned serial-level base document: the marker facts
// in parsed (design.md §Interfaces §1) and an empty probe object.
func serialDoc(dirName string) map[string]any {
	return map[string]any{
		"parsed": map[string]any{
			"serial_record":        true,
			"dir_name_raw":         dirName,
			"backing":              "directory",
			"series_relative_path": dirName,
			"relative_path":        dirName,
		},
		"ffprobe": json.RawMessage(`{}`),
	}
}

