// putSeriesRow upserts a series row (the scan-side shape) and returns its
// minted row id.
func putSeriesRow(t *testing.T, s *store.Store, moduleID string, libID int64, rel, status string, doc map[string]any) string {
	t.Helper()
	docBytes, err := json.Marshal(doc)
	if err != nil {
		t.Fatalf("marshal series doc: %v", err)
	}
	if err := s.PutSeries(context.Background(), store.Series{
		ModuleID: moduleID, LibraryID: libID, RelativePath: rel,
		Document: docBytes, SchemaVersion: 1, Status: status,
	}); err != nil {
		t.Fatalf("PutSeries %s: %v", rel, err)
	}
	sr, err := s.GetSeriesByPath(context.Background(), libID, rel)
	if err != nil {
		t.Fatalf("GetSeriesByPath %s: %v", rel, err)
	}
	return sr.ID
}

