// parserFake is the serial-parser stand-in: Match self-selects the series
// document (applies=false otherwise); Convert cleans the directory name into a
// display title and extracts a trailing season token. It mirrors the shipped
// plugin's semantics with a minimal local copy — the parse grammar itself is
// owned (and tested) by the plugins package.
func parserFake() *fnSource {
	seasonTail := regexp.MustCompile(`(?i)(?:^|[\s._-])s(\d{1,3})$`)
	return &fnSource{
		id: "serial-parser",
		match: func(req *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
			f := req.GetItem().GetParsed().GetFields()
			if !f["serial_record"].GetBoolValue() {
				return &metadatav1.MatchResult{Applies: false, Reason: "not a serial record"}, nil
			}
			q, _ := structpb.NewStruct(map[string]any{"dir_name_raw": f["dir_name_raw"].GetStringValue()})
			return &metadatav1.MatchResult{Applies: true, Query: q, Confidence: 1.0}, nil
		},
		convert: func(req *metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
			raw := req.GetQuery().GetFields()["dir_name_raw"].GetStringValue()
			meta := map[string]any{"title": strings.ReplaceAll(raw, ".", " ")}
			if m := seasonTail.FindStringSubmatch(raw); m != nil {
				meta["season"] = int64(mustAtoi(m[1]))
				meta["title"] = strings.TrimSpace(strings.TrimSuffix(strings.ReplaceAll(raw, ".", " "), " S"+m[1]))
			}
			st, _ := structpb.NewStruct(meta)
			return &metadatav1.ConvertResult{Metadata: st}, nil
		},
	}
}

func mustAtoi(s string) int { n, _ := strconv.Atoi(s); return n }

// metaSource is a source that applies unconditionally and converts to a fixed
// metadata map (the success path for ledger-machinery tests).
func metaSource(id string, meta map[string]any) *fnSource {
	return &fnSource{
		id: id,
		convert: func(*metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
			st, _ := structpb.NewStruct(meta)
			return &metadatav1.ConvertResult{Metadata: st}, nil
		},
	}
}

// grabberFake is the frame-grabber stand-in: it applies only to documents that
// are NOT serial records and carry a video absolute path (a series document
// never qualifies — Match skips it, the core records a skipped stage).
func grabberFake() *fnSource {
	return &fnSource{
		id: "frame-grabber",
		match: func(req *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
			f := req.GetItem().GetParsed().GetFields()
			if f["serial_record"].GetBoolValue() || f["absolute_path"].GetStringValue() == "" {
				return &metadatav1.MatchResult{Applies: false, Reason: "no video absolute path"}, nil
			}
			return &metadatav1.MatchResult{Applies: true, Confidence: 1.0}, nil
		},
		convert: func(*metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
			st, _ := structpb.NewStruct(map[string]any{"thumbnail_path": "thumbs/fake/frame.jpg"})
			return &metadatav1.ConvertResult{Metadata: st}, nil
		},
	}
}

// serialResolver resolves the serials chain fakes; the short backoff/attempt
// knobs keep the terminal paths fast.
func serialResolver(res map[string]sdk.MetadataSource) metadataResolver {
	return mapResolver(res).resolver()
}

func fastQueueCfg() QueueConfig {
	return QueueConfig{
		Workers: 1, MaxAttempts: 1, Backoff: time.Millisecond,
		ExhaustedCool: 50 * time.Millisecond, // exhausted cooldown elapses within the test
		NoDataCool:    time.Hour,             // no_data stays cooling for the whole test
	}
}

// waitForSeriesStatus polls the series row until it reaches want.
func waitForSeriesStatus(t *testing.T, s *store.Store, id, want string, timeout time.Duration) store.Series {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		sr, err := s.GetSeries(context.Background(), id)
		if err == nil && sr.Status == want {
			return sr
		}
		time.Sleep(time.Millisecond)
	}
	sr, _ := s.GetSeries(context.Background(), id)
	t.Fatalf("series %s status = %q, want %q (timeout %v)", id, sr.Status, want, timeout)
	return sr
}

// waitForLedger polls until every (row, plugin) pair carries the wanted ledger
// status.
func waitForLedger(t *testing.T, s *store.Store, want map[[2]string]string, timeout time.Duration) {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		rows, err := s.ListFailures(context.Background())
		if err == nil {
			got := map[[2]string]string{}
			for _, r := range rows {
				got[[2]string{r.ItemID, r.PluginID}] = r.Status
			}
			ok := true
			for k, v := range want {
				if got[k] != v {
					ok = false
					break
				}
			}
			if ok {
				return
			}
		}
		time.Sleep(time.Millisecond)
	}
	t.Fatalf("ledger pairs not reached within %v: want %v", timeout, want)
}

// ledgerPairs snapshots the current ledger as a (row, plugin) -> status map.
func ledgerPairs(t *testing.T, s *store.Store) map[[2]string]string {
	t.Helper()
	rows, err := s.ListFailures(context.Background())
	if err != nil {
		t.Fatalf("ListFailures: %v", err)
	}
	out := map[[2]string]string{}
	for _, r := range rows {
		out[[2]string{r.ItemID, r.PluginID}] = r.Status
	}
	return out
}

// TestSeriesLedgerAndRestart is the loop-safety contract over BOTH stores
// (serials-library D5 / box 3.1): derivation covers items and series rows
// alike, terminal failures ledger per (row, plugin) pair, a restart re-derives
// the eligible pending work while pairs inside their ledger cooldown stay
// skipped, and a successful run clears a prior row.
func TestSeriesLedgerAndRestart(t *testing.T) {
	s, reg := queueTestStore(t)
	seriesID, itemID := twoLevelFixture(t, s, "pending")

	ctx := context.Background()

	// Derivation covers BOTH rows under the identical predicates: two queueable
	// sources each -> four pending tasks.
	q := NewQueue(Deps{Store: s, Modules: reg}, fastQueueCfg())
	tasks, err := q.deriveLibrary(ctx, 1)
	if err != nil {
		t.Fatalf("deriveLibrary: %v", err)
	}
	if len(tasks) != 4 {
		t.Fatalf("derived %d tasks, want 4 (2 rows x 2 sources): %+v", len(tasks), tasks)
	}

	// Phase 1: parser Match errors (terminal exhausted, short cooldown);
	// frame-grabber runs clean but yields nothing (terminal no_data, long
	// cooldown). Both rows drain to the ledger.
	fail := &matchErrSource{id: "fail"}
	noData := &fnSource{id: "no_data"}
	q.resolve = serialResolver(map[string]sdk.MetadataSource{
		"serial-parser": fail, "frame-grabber": noData,
	})
	if err := q.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	q.Notify(ctx, 1)
	waitForLedger(t, s, map[[2]string]string{
		{seriesID, "serial-parser"}: "exhausted",
		{seriesID, "frame-grabber"}: "no_data",
		{itemID, "serial-parser"}:   "exhausted",
		{itemID, "frame-grabber"}:   "no_data",
	}, 3*time.Second)
	q.Stop()

	// Every pair is inside its cooldown -> derivation must yield nothing.
	tasks, err = q.deriveLibrary(ctx, 1)
	if err != nil {
		t.Fatalf("deriveLibrary after drain: %v", err)
	}
	if len(tasks) != 0 {
		t.Fatalf("cooling pairs re-derived: %+v", tasks)
	}

	// A re-scan refreshes both rows (fresh documents, status stale — the scan
	// semantics) and the exhausted cooldown elapses; the no_data cooldown does
	// not.
	twoLevelFixture(t, s, "stale")
	time.Sleep(120 * time.Millisecond) // > ExhaustedCool (50ms)

	// Phase 2 (restart): parser succeeds now (an always-applying source — both
	// rows must re-drain); frame-grabber still no_data. The exhausted rows are
	// eligible and re-derived; the no_data rows stay skipped.
	q.resolve = serialResolver(map[string]sdk.MetadataSource{
		"serial-parser": metaSource("serial-parser", map[string]any{"title": "Show Name"}),
		"frame-grabber": noData,
	})
	if err := q.Start(ctx); err != nil {
		t.Fatalf("restart Start: %v", err)
	}
	defer q.Stop()
	q.Notify(ctx, 1)
	_ = waitForStatus(t, s, itemID, statusReady, 3*time.Second)
	sr := waitForSeriesStatus(t, s, seriesID, statusReady, 3*time.Second)

	// Success wrote the namespace and CLEARED the prior exhausted row; the
	// cooling no_data pair was never re-drained (no namespace, row intact).
	for _, id := range []string{seriesID, itemID} {
		doc := decodeDoc(rowDocument(t, s, id))
		sources, _ := doc["sources"].(map[string]any)
		if sources["serial-parser"] == nil {
			t.Fatalf("row %s: sources.serial-parser missing after restart: %v", id, doc)
		}
		if sources["frame-grabber"] != nil {
			t.Fatalf("row %s: cooling frame-grabber pair was re-drained: %v", id, sources)
		}
	}
	pairs := ledgerPairs(t, s)
	for _, id := range []string{seriesID, itemID} {
		if _, ok := pairs[[2]string{id, "serial-parser"}]; ok {
			t.Fatalf("row %s: success did not clear the prior exhausted row", id)
		}
		if pairs[[2]string{id, "frame-grabber"}] != "no_data" {
			t.Fatalf("row %s: no_data ledger row vanished: %v", id, pairs)
		}
	}
	_ = sr
}

// rowDocument returns the current opaque document of an item or series row.
func rowDocument(t *testing.T, s *store.Store, id string) json.RawMessage {
	t.Helper()
	if it, err := s.GetItem(context.Background(), id); err == nil {
		return it.Document
	}
	sr, err := s.GetSeries(context.Background(), id)
	if err != nil {
		t.Fatalf("row %s unreadable as item and series: %v", id, err)
	}
	return sr.Document
}

// TestSeriesEnrichedViaParser is the series-level enrichment contract
// (serials-library box 3.2's core half): the queue drains a series row through
// the chain and the document gains exactly the parser's namespace plus the
// core-stamped _provenance/_view/_stages — no other namespace.
func TestSeriesEnrichedViaParser(t *testing.T) {
	s, reg := queueTestStore(t)
	seriesID, _ := twoLevelFixture(t, s, "pending")
	ctx := context.Background()

	q := NewQueue(Deps{Store: s, Modules: reg}, fastQueueCfg())
	q.resolve = serialResolver(map[string]sdk.MetadataSource{
		"serial-parser": parserFake(), "frame-grabber": grabberFake(),
	})
	if err := q.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer q.Stop()
	q.Notify(ctx, 1)
	sr := waitForSeriesStatus(t, s, seriesID, statusReady, 3*time.Second)

	doc := decodeDoc(sr.Document)
	sources, ok := doc["sources"].(map[string]any)
	if !ok || len(sources) != 1 {
		t.Fatalf("sources = %v, want exactly one namespace", doc["sources"])
	}
	ns, ok := sources["serial-parser"].(map[string]any)
	if !ok {
		t.Fatalf("sources.serial-parser missing: %v", sources)
	}
	// The cleaned display title (separators normalized, season token extracted
	// out of the title) and the extracted season.
	if ns["title"] != "Show Name" {
		t.Fatalf("title = %v, want %q", ns["title"], "Show Name")
	}
	if ns["season"] != float64(1) {
		t.Fatalf("season = %v, want 1", ns["season"])
	}
	// Core-stamped machinery: per-field provenance, a view projection, stage
	// history — none of them named by the plugin's namespace.
	prov, _ := doc["_provenance"].(map[string]any)
	titleProv, _ := prov["title"].(map[string]any)
	if titleProv["plugin_id"] != "serial-parser" {
		t.Fatalf("_provenance.title = %v, want serial-parser", titleProv)
	}
	view, _ := doc["_view"].(map[string]any)
	titleView, _ := view["title"].(map[string]any)
	if titleView["source"] != "serial-parser" {
		t.Fatalf("_view.title = %v, want serial-parser", titleView)
	}
	stages, _ := doc["_stages"].([]map[string]any)
	if len(stages) < 2 {
		t.Fatalf("_stages = %v, want entries for both chain stages", doc["_stages"])
	}
}

// TestSeriesSettlesIndependently is box 3.4: a series settles ready as soon as
// every queueable source of the SERIES reached a terminal outcome — the episode
// item's own progress never gates it.
func TestSeriesSettlesIndependently(t *testing.T) {
	s, reg := queueTestStore(t)
	seriesID, itemID := twoLevelFixture(t, s, "pending")
	ctx := context.Background()

	// For the series: parser succeeds, grabber skips (no video path) — both
	// terminal. For the episode: both sources skip — the episode never enriches
	// and can never settle, so a ready series next to a pending episode proves
	// the independence.
	q := NewQueue(Deps{Store: s, Modules: reg}, fastQueueCfg())
	q.resolve = serialResolver(map[string]sdk.MetadataSource{
		"serial-parser": parserFake(), "frame-grabber": grabberFake(),
	})
	if err := q.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer q.Stop()
	q.Notify(ctx, 1)

	sr := waitForSeriesStatus(t, s, seriesID, statusReady, 3*time.Second)
	it, err := s.GetItem(ctx, itemID)
	if err != nil {
		t.Fatalf("GetItem episode: %v", err)
	}
	if it.Status != statusPending {
		t.Fatalf("episode status = %q, want still pending (series settle must not wait for it)", it.Status)
	}
	doc := decodeDoc(sr.Document)
	sources, _ := doc["sources"].(map[string]any)
	if sources["serial-parser"] == nil {
		t.Fatalf("series sources = %v, want serial-parser", sources)
	}
}

// TestPosterOutranksFrameGrab and TestViewPrecedenceOverFrameGrab are box 3.7:
// a later-priority source writing an image view entry outranks the frame-grab
// default in _view (last-writer until B3 arbitration), while BOTH namespaces
// stay stored losslessly.
func TestPosterOutranksFrameGrab(t *testing.T) {
	runViewPrecedence(t)
}

func TestViewPrecedenceOverFrameGrab(t *testing.T) {
	runViewPrecedence(t)
}

func runViewPrecedence(t *testing.T) {
	t.Helper()
	ctx := context.Background()

	// The chain shape of the serials module: frame-grabber at priority 2 runs
	// BEFORE a later source (priority 3) that also writes an image view entry.
	mod := module.Module{
		ID: "serial", MediaType: "serial", SchemaVersion: 1,
		MetadataSources: []module.MetadataSourceBinding{
			{PluginID: "frame-grabber", CapabilityID: "default", Priority: 2, Enabled: true},
			{PluginID: "poster-source", CapabilityID: "default", Priority: 3, Enabled: true},
		},
	}
	frame := &fnSource{
		id: "frame-grabber",
		match: func(req *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
			f := req.GetItem().GetParsed().GetFields()
			if f["serial_record"].GetBoolValue() || f["absolute_path"].GetStringValue() == "" {
				return &metadatav1.MatchResult{Applies: false}, nil
			}
			return &metadatav1.MatchResult{Applies: true}, nil
		},
		convert: func(*metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
			st, _ := structpb.NewStruct(map[string]any{"image": "thumbs/ab/cd.jpg"})
			return &metadatav1.ConvertResult{Metadata: st}, nil
		},
	}
	poster := &fnSource{
		id: "poster-source",
		convert: func(*metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
			st, _ := structpb.NewStruct(map[string]any{"image": "https://cdn/example.jpg"})
			return &metadatav1.ConvertResult{Metadata: st}, nil
		},
	}

	doc := map[string]any{
		"parsed": map[string]any{
			"relative_path":        "Show/Show.S01E01.mkv",
			"series_relative_path": "Show",
			"absolute_path":        "/libs/root/Show/Show.S01E01.mkv",
		},
	}
	got, status, res, err := enrichDoc(ctx, mapResolver{"frame-grabber": frame, "poster-source": poster}.resolver(),
		mod, doc, reconstructBase(doc), nil)
	if err != nil {
		t.Fatalf("enrichDoc: %v", err)
	}
	if status != statusEnriched {
		t.Fatalf("status = %q, want enriched", status)
	}
	if res.Succeeded != 2 {
		t.Fatalf("Succeeded = %d, want 2", res.Succeeded)
	}

	// Both namespaces stored losslessly.
	sources, _ := got["sources"].(map[string]any)
	frameNS, _ := sources["frame-grabber"].(map[string]any)
	posterNS, _ := sources["poster-source"].(map[string]any)
	if frameNS["image"] != "thumbs/ab/cd.jpg" {
		t.Fatalf("frame-grabber namespace lost: %v", sources)
	}
	if posterNS["image"] != "https://cdn/example.jpg" {
		t.Fatalf("poster-source namespace lost: %v", sources)
	}

	// The view surfaces the LATER source's image entry.
	view, _ := got["_view"].(map[string]any)
	imageView, _ := view["image"].(map[string]any)
	if imageView["value"] != "https://cdn/example.jpg" || imageView["source"] != "poster-source" {
		t.Fatalf("_view.image = %v, want the later poster-source entry", imageView)
	}
	prov, _ := got["_provenance"].(map[string]any)
	imageProv, _ := prov["image"].(map[string]any)
	if imageProv["plugin_id"] != "poster-source" {
		t.Fatalf("_provenance.image = %v, want poster-source", imageProv)
	}
}
